import sys

def parse_time(time_str):
    parts = time_str.split()
    hh_mm = parts[0]
    period = parts[1]
    hh, mm = map(int, hh_mm.split(':'))
    if period == 'AM':
        if hh == 12:
            hh = 0
    else:
        if hh != 12:
            hh += 12
    return hh * 60 + mm

def main():
    input_data = sys.stdin.read().splitlines()
    idx = 0
    while idx < len(input_data):
        line = input_data[idx].strip()
        if not line:
            idx += 1
            continue
        break

    if idx >= len(input_data):
        return

    try:
        T = int(line)
    except ValueError:
        return
    idx += 1

    results = []

    for _ in range(T):
        while idx < len(input_data) and not input_data[idx].strip():
            idx += 1
        if idx >= len(input_data):
            break

        P_str = input_data[idx].strip()
        idx += 1

        while idx < len(input_data) and not input_data[idx].strip().isdigit():
            idx += 1
        if idx >= len(input_data) or not input_data[idx].strip().isdigit():
            break

        N = int(input_data[idx].strip())
        idx += 1

        P = parse_time(P_str)

        output_chars = []

        for _ in range(N):
            line = input_data[idx].strip()
            idx += 1
            parts = line.split()
            L_str = parts[0] + " " + parts[1]
            R_str = parts[2] + " " + parts[3]

            L = parse_time(L_str)
            R = parse_time(R_str)

            if L <= P <= R:
                output_chars.append('1')
            else:
                output_chars.append('0')

        results.append("".join(output_chars))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
